import {
    Table,
    IntegerColumn,
    DurationColumn,
    BooleanColumn,
    GenericColumn,
    ReferenceColumn,
    StringColumn,
    DayOfWeekColumn,
    DaysOfWeekColumn,
    TimeColumn,
    DateTimeColumn,
    CalendarDateTimeColumn,
    GuidColumn,
} from '../../db'

export const sysauto = Table({
    allowWebServiceAccess: true,
    extends: 'sys_metadata',
    extensible: true,
    label: 'Scheduled Job',
    name: 'sysauto',
    schema: {
        offset_type: IntegerColumn({
            default: '0',
            choices: {
                1: {
                    label: 'Future',
                    sequence: 1,
                },
                2: {
                    label: 'Past',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Offset type',
        }),
        offset: DurationColumn({
            label: 'Offset',
            maxLength: 40,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        conditional: BooleanColumn({
            label: [
                {
                    hint: 'Specify conditions under which this job is executed',
                    label: 'Conditional',
                    plural: 'Conditionals',
                    language: 'en',
                },
            ],
        }),
        condition: GenericColumn({
            columnType: 'script_plain',
            label: [
                {
                    hint: 'Execute this job only if script evaluates to true',
                    label: 'Condition',
                    plural: 'Conditions',
                    language: 'en',
                },
            ],
            maxLength: 8000,
        }),
        run_as: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'restrict',
            default: 'javascript:gs.getUserID()',
            label: [
                {
                    hint: 'Scheduled job will run with credentials of specified user (optional)',
                    label: 'Run as',
                    plural: 'Run as',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
        }),
        run_as_tz: StringColumn({
            dropdown: 'dropdown_with_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'sys_user',
                field: 'time_zone',
            },
            label: 'Run as tz',
        }),
        run_type: StringColumn({
            default: 'daily',
            choices: {
                daily: {
                    label: 'Daily',
                    sequence: 0,
                },
                day_and_month_in_year: {
                    label: 'Day and Month in Year',
                    sequence: 1,
                },
                weekly: {
                    label: 'Weekly',
                    sequence: 2,
                },
                monthly: {
                    label: 'Monthly',
                    sequence: 3,
                },
                day_week_month_year: {
                    label: 'Day in Week in Month in Year',
                    sequence: 4,
                },
                periodically: {
                    label: 'Periodically',
                    sequence: 5,
                },
                once: {
                    label: 'Once',
                    sequence: 6,
                },
                on_demand: {
                    label: 'On Demand',
                    sequence: 7,
                },
                week_in_month: {
                    label: 'Week in Month',
                    sequence: 8,
                },
                business_calendar_start: {
                    label: 'Business Calendar: Entry Start',
                    sequence: 50,
                    hint: 'Refers to Business Calendar entry spans',
                },
                business_calendar_end: {
                    label: 'Business Calendar: Entry End',
                    sequence: 51,
                    hint: 'Refers to Business Calendar entry spans',
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Run',
        }),
        run_dayofweek: DayOfWeekColumn({
            label: 'Day',
        }),
        run_daysofweek: DaysOfWeekColumn({
            label: [
                {
                    hint: 'Specify days of week to run the job',
                    label: 'Run days of week',
                    plural: 'Run days of weeks',
                    language: 'en',
                },
            ],
        }),
        run_dayofmonth: IntegerColumn({
            default: '1',
            choices: {
                1: {
                    label: '1',
                    sequence: 1,
                },
                2: {
                    label: '2',
                    sequence: 2,
                },
                3: {
                    label: '3',
                    sequence: 3,
                },
                4: {
                    label: '4',
                    sequence: 4,
                },
                5: {
                    label: '5',
                    sequence: 5,
                },
                6: {
                    label: '6',
                    sequence: 6,
                },
                7: {
                    label: '7',
                    sequence: 7,
                },
                8: {
                    label: '8',
                    sequence: 8,
                },
                9: {
                    label: '9',
                    sequence: 9,
                },
                10: {
                    label: '10',
                    sequence: 10,
                },
                11: {
                    label: '11',
                    sequence: 11,
                },
                12: {
                    label: '12',
                    sequence: 12,
                },
                13: {
                    label: '13',
                    sequence: 13,
                },
                14: {
                    label: '14',
                    sequence: 14,
                },
                15: {
                    label: '15',
                    sequence: 15,
                },
                16: {
                    label: '16',
                    sequence: 16,
                },
                17: {
                    label: '17',
                    sequence: 17,
                },
                18: {
                    label: '18',
                    sequence: 18,
                },
                19: {
                    label: '19',
                    sequence: 19,
                },
                20: {
                    label: '20',
                    sequence: 20,
                },
                21: {
                    label: '21',
                    sequence: 21,
                },
                22: {
                    label: '22',
                    sequence: 22,
                },
                23: {
                    label: '23',
                    sequence: 23,
                },
                24: {
                    label: '24',
                    sequence: 24,
                },
                25: {
                    label: '25',
                    sequence: 25,
                },
                26: {
                    label: '26',
                    sequence: 26,
                },
                27: {
                    label: '27',
                    sequence: 27,
                },
                28: {
                    label: '28',
                    sequence: 28,
                },
                29: {
                    label: '29',
                    sequence: 29,
                },
                30: {
                    label: '30',
                    sequence: 30,
                },
                31: {
                    label: '31',
                    sequence: 31,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Day',
        }),
        run_weekinmonth: GenericColumn({
            columnType: 'week_of_month',
            choices: {
                1: {
                    label: 'First',
                },
                2: {
                    label: 'Second',
                },
                3: {
                    label: 'Third',
                },
                4: {
                    label: 'Fourth',
                },
                5: {
                    label: 'Fifth',
                },
                6: {
                    label: 'Sixth',
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Run week in month',
        }),
        run_month: GenericColumn({
            columnType: 'month_of_year',
            label: 'Month',
        }),
        run_time: TimeColumn({
            label: 'Time',
            maxLength: 40,
        }),
        run_period: DurationColumn({
            label: 'Repeat Interval',
            maxLength: 40,
        }),
        run_start: DateTimeColumn({
            default: 'javascript:gs.nowDateTime()',
            label: 'Starting',
        }),
        max_drift: DurationColumn({
            label: 'Max drift',
            maxLength: 40,
        }),
        advanced: BooleanColumn({
            label: 'Advanced',
        }),
        run_end: DateTimeColumn({
            label: [
                {
                    hint: 'Specify when the job should stop running. Jobs with ending values in the past are marked inactive',
                    label: 'Ending',
                    plural: 'Endings',
                    language: 'en',
                },
            ],
        }),
        repeat_every: IntegerColumn({
            label: [
                {
                    hint: 'For recurring trigger types, repeat only every Nth occurrence. For example, if a daily job is expected to run every 3rd day, this field would be set to 3',
                    label: 'Repeat every',
                    plural: 'Repeat everies',
                    language: 'en',
                },
            ],
        }),
        upgrade_safe: BooleanColumn({
            default: false,
            label: 'Upgrade safe',
        }),
        time_zone: StringColumn({
            attributes: {
                choice_script: "new GlideTimeZoneUtil().process('sysauto')",
            },
            script: "new GlideTimeZoneUtil().process('sysauto')",
            choices: {
                floating: {
                    label: 'Use System Time Zone',
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Time zone',
        }),
        entered_run_start: CalendarDateTimeColumn({
            attributes: {
                time_zone_value: 'UTC',
            },
            label: [
                {
                    hint: 'A recurring job will not start until Starting date/time is reached.',
                    label: 'Starting',
                    plural: 'Startings',
                    language: 'en',
                },
            ],
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        name: StringColumn({
            attributes: {
                no_truncate: true,
            },
            label: 'Name',
            maxLength: 100,
        }),
        entered_time: GenericColumn({
            attributes: {
                user_time_format: true,
            },
            columnType: 'glide_utc_time',
            label: 'Time',
        }),
        business_calendar: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Business Calendar',
            referenceTable: 'business_calendar',
            referenceQual: 'is_legacy_schedule=false',
        }),
        entered_run_end: CalendarDateTimeColumn({
            attributes: {
                time_zone_value: 'UTC',
            },
            label: [
                {
                    hint: 'Specify when the job should stop running. Jobs with Ending values in the past are marked inactive',
                    label: 'Ending',
                    plural: 'Endings',
                    language: 'en',
                },
            ],
        }),
    },
    textIndex: true,
})
